// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.locks.LockSupport;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.BooleanSupplier;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Runs the applier loop on one dedicated daemon thread. The thread runs the loop body while it reports work and parks
 * otherwise; {@link #wake()} sets a flag and unparks it, so a wake that arrives while the body runs is never lost.
 * Delayed tasks run on a one-thread scheduled executor and only enqueue applier work.
 * <p>
 * Tests may {@link #pause()} the loop at a unit boundary and run units themselves with {@link #stepWhilePaused()}; the
 * applier's state is confined to whichever thread runs the body, and while paused that is the caller.
 */
final class ThreadApplierScheduler implements ApplierScheduler {

	private static final Logger logger = LoggerFactory.getLogger(ThreadApplierScheduler.class);

	private final String threadName;
	private final AtomicBoolean pending = new AtomicBoolean();
	private final AtomicBoolean shutdown = new AtomicBoolean();
	private final ScheduledThreadPoolExecutor timers;
	/** Polls before parking when a unit found nothing more to do; a wake in flight costs this much, not a park. */
	static final int IDLE_SPINS_BEFORE_PARK = 256;
	private final Object pauseMonitor = new Object();
	/** Every unit runs under this lock: the loop thread's, a paused test's step, or a waiting committer's. */
	private final ReentrantLock unitLock = new ReentrantLock();
	private volatile boolean parked;
	private boolean paused;
	private boolean pauseAcknowledged;
	private volatile Thread thread;
	private volatile BooleanSupplier body;

	ThreadApplierScheduler(String threadName) {
		this.threadName = threadName;
		this.timers = new ScheduledThreadPoolExecutor(1, runnable -> {
			Thread timer = new Thread(runnable, threadName + "-timer");
			timer.setDaemon(true);
			return timer;
		});
		timers.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);
		timers.setRemoveOnCancelPolicy(true);
	}

	@Override
	public void start(BooleanSupplier runOne) {
		if (thread != null) {
			throw new IllegalStateException("scheduler already started");
		}
		body = runOne;
		Thread loop = new Thread(() -> run(runOne), threadName);
		loop.setDaemon(true);
		thread = loop;
		loop.start();
	}

	private void run(BooleanSupplier runOne) {
		while (!shutdown.get()) {
			awaitUnpaused();
			if (shutdown.get()) {
				return;
			}
			pending.set(false);
			boolean worked;
			unitLock.lock();
			try {
				worked = runOne.getAsBoolean();
			} catch (RuntimeException | Error failure) {
				// runOne handles its own failures; this is a last resort so the thread survives
				logger.error("Adjacency applier loop threw; continuing", failure);
				worked = true;
			} finally {
				unitLock.unlock();
			}
			if (worked) {
				continue;
			}
			// Committers apply their own records (helpOnce), so this thread mostly runs worker outcomes, whose
			// latency does not gate a commit: poll briefly for a wake that is already on its way, then park rather
			// than burn a core yielding.
			for (int spin = 0; spin < IDLE_SPINS_BEFORE_PARK && !pending.get(); spin++) {
				Thread.onSpinWait();
			}
			parked = true;
			try {
				while (!pending.get() && !shutdown.get() && !isPaused()) {
					LockSupport.park(this);
				}
			} finally {
				parked = false;
			}
		}
	}

	@Override
	public boolean helpOnce() {
		BooleanSupplier runOne = body;
		if (runOne == null || shutdown.get() || isPaused() || !unitLock.tryLock()) {
			return false;
		}
		try {
			if (isPaused()) {
				return false;
			}
			return runOne.getAsBoolean();
		} finally {
			unitLock.unlock();
		}
	}

	/** Test seam: whether the loop thread is spinning or running rather than parked. */
	boolean loopThreadIsRunningForTest() {
		return !parked;
	}

	@Override
	public void wake() {
		pending.set(true);
		Thread loop = thread;
		if (loop != null) {
			LockSupport.unpark(loop);
		}
	}

	@Override
	public void schedule(Runnable task, long delayMillis) {
		if (shutdown.get()) {
			return;
		}
		try {
			timers.schedule(task, delayMillis, TimeUnit.MILLISECONDS);
		} catch (RejectedExecutionException rejected) {
			logger.debug("Adjacency applier timer rejected after shutdown", rejected);
		}
	}

	@Override
	public void shutdown() {
		if (!shutdown.compareAndSet(false, true)) {
			return;
		}
		timers.shutdownNow();
		synchronized (pauseMonitor) {
			paused = false;
			pauseMonitor.notifyAll();
		}
		wake();
		// the applier's state is confined to the loop thread; the caller may touch it only once the loop has stopped
		Thread loop = thread;
		if (loop != null && loop != Thread.currentThread()) {
			try {
				loop.join(TimeUnit.SECONDS.toMillis(30));
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
		}
	}

	private void awaitUnpaused() {
		synchronized (pauseMonitor) {
			while (paused && !shutdown.get()) {
				pauseAcknowledged = true;
				pauseMonitor.notifyAll();
				try {
					pauseMonitor.wait();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					return;
				}
			}
		}
	}

	/** Test seam: stops the loop thread at its next unit boundary and returns once it has stopped. */
	void pause() {
		synchronized (pauseMonitor) {
			if (paused) {
				return;
			}
			paused = true;
			pauseAcknowledged = false;
		}
		wake();
		synchronized (pauseMonitor) {
			Thread loop = thread;
			while (!pauseAcknowledged && !shutdown.get() && loop != null && loop.isAlive()) {
				try {
					pauseMonitor.wait(50);
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					return;
				}
			}
		}
	}

	/** Test seam: lets the loop thread continue. */
	void resume() {
		synchronized (pauseMonitor) {
			paused = false;
			pauseAcknowledged = false;
			pauseMonitor.notifyAll();
		}
		wake();
	}

	boolean isPaused() {
		synchronized (pauseMonitor) {
			return paused;
		}
	}

	/** Test seam: runs one unit on the caller's thread while the loop thread is paused. */
	boolean stepWhilePaused() {
		synchronized (pauseMonitor) {
			Thread loop = thread;
			if (!paused || (!pauseAcknowledged && loop != null && loop.isAlive() && !shutdown.get())) {
				throw new IllegalStateException("the applier loop is not paused");
			}
		}
		BooleanSupplier runOne = body;
		if (runOne == null) {
			return false;
		}
		unitLock.lock();
		try {
			return runOne.getAsBoolean();
		} finally {
			unitLock.unlock();
		}
	}
}
